// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CloudSSHNode) predicate.CloudSSHNode {
	return predicate.CloudSSHNode(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CloudSSHNode) predicate.CloudSSHNode {
	return predicate.CloudSSHNode(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CloudSSHNode) predicate.CloudSSHNode {
	return predicate.CloudSSHNode(sql.NotPredicates(p))
}
